(() => {
  const canvas=document.getElementById('battlefield'),ctx=canvas.getContext('2d'),$=id=>document.getElementById(id);
  const ui={credits:$('credits'),income:$('income'),power:$('power'),army:$('army-count'),type:$('selection-type'),name:$('selection-name'),icon:$('selection-icon'),health:$('selection-health'),toast:$('toast'),start:$('start-screen'),pause:$('pause-screen'),end:$('end-screen'),objective:$('objective-card')};
  const factions={usa:{label:'UNITED STATES',color:'#69a9d8',accent:'#8bc9f1',hq:'Forward Command',collector:'Supply Chinook',infantry:'Ranger Squad',tank:'Paladin Tank',scout:'Humvee',power:'Field Generator',barracks:'Training Center',factory:'War Factory',defense:'Patriot Battery'},china:{label:'CHINA',color:'#db6554',accent:'#f1ab53',hq:'War Command',collector:'Supply Truck',infantry:'Red Guard',tank:'Dragon Tank',scout:'Gatling Tank',power:'Nuclear Reactor',barracks:'Barracks',factory:'War Factory',defense:'Gattling Cannon'},russia:{label:'RUSSIA',color:'#8caa75',accent:'#dfbd66',hq:'Field Headquarters',collector:'Ore Truck',infantry:'Conscripts',tank:'T-90 Tank',scout:'BTR Scout',power:'Power Plant',barracks:'Training Hall',factory:'Armor Plant',defense:'Sentry Cannon'}};
  const factionDefs={usa:{power:450,barracks:600,factory:900,defense:500,infantry:300,tank:950,scout:550,collector:700},china:{power:400,barracks:550,factory:850,defense:450,infantry:240,tank:850,scout:500,collector:650},russia:{power:500,barracks:650,factory:1000,defense:550,infantry:280,tank:900,scout:600,collector:750}};
  let width=0,height=0,dpr=1,playing=false,paused=false,over=false,credits=3500,time=0,last=0,toastTimer=0,action='select',selected=null,shots=[],particles=[],shake=0;
  let faction='usa',units=[],enemies=[],buildings=[],decor=[],nodes=[],camera={x:.5,y:.5,z:1},serial=0,enemyTimer=20,placement=null,activeTab='structures',selectedIds=[];
  const clamp=(n,a,b)=>Math.max(a,Math.min(b,n)),rand=(a,b)=>a+Math.random()*(b-a);
  const unitStats={infantry:{hp:42,speed:45,range:105,damage:7,rate:.9,radius:8,icon:'♟',type:'Infantry'},tank:{hp:130,speed:32,range:150,damage:19,rate:1.35,radius:14,icon:'▰',type:'Armor'},scout:{hp:72,speed:64,range:118,damage:9,rate:.75,radius:11,icon:'◈',type:'Recon'},collector:{hp:100,speed:38,range:0,damage:0,rate:1,radius:13,icon:'⬡',type:'Harvester'}};
  const structures={power:{cost:'power',type:'Power',hp:180,size:32,icon:'ϟ'},barracks:{cost:'barracks',type:'Infantry production',hp:220,size:36,icon:'▤'},factory:{cost:'factory',type:'Vehicle production',hp:280,size:42,icon:'▰'},defense:{cost:'defense',type:'Defense',hp:250,size:28,icon:'⊕'}};
  const names={};
  function resize(){const r=canvas.getBoundingClientRect();width=r.width;height=r.height;dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(width*dpr);canvas.height=Math.round(height*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);draw()}
  function makeBuilding(kind,team,x,y){const def=structures[kind]||{hp:500,size:50,icon:'⌂',type:'Command'};const f=factions[faction];const label=team==='blue'?(kind==='hq'?f.hq:f[kind]||kind):(kind==='hq'?'Enemy Command Center':'Enemy Outpost');return {id:'b'+(++serial),kind,team,name:label,type:kind==='hq'?'Command Center':def.type,icon:def.icon,x,y,hp:def.hp,max:def.hp,size:def.size,range:kind==='defense'?150:kind==='hq'?120:0,damage:kind==='defense'?13:kind==='hq'?8:0,rate:kind==='defense'?1.1:1.5,cool:rand(.2,1),target:null}}
  function setup(){units=[];enemies=[];buildings=[];shots=[];particles=[];credits=3500;time=0;serial=0;over=false;paused=false;placement=null;camera={x:.5,y:.5,z:1};selectedIds=[];enemyTimer=22;
    const hq=makeBuilding('hq','blue',.13,.53);buildings.push(hq);selected=hq;
    buildings.push(makeBuilding('hq','red',.88,.45));
    units.push(createUnit('scout',.19,.57));units.push(createUnit('infantry',.20,.62));units.push(createUnit('infantry',.18,.66));
    decor=[];nodes=[];let seed=29481;const random=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296};
    for(let i=0;i<320;i++){let x=random(),y=random();if((x<.23&&y>.4&&y<.7)||(x>.78&&y>.3&&y<.6))continue;decor.push({x,y,r:2+random()*11,kind:random()<.65?'bush':'rock',tone:random(),rot:random()})}
    for(let i=0;i<22;i++){let x=.25+random()*.5,y=.08+random()*.83;nodes.push({x,y,amount:900,active:true})}
    camera.x=.5;camera.y=.5;refreshUI();renderBuilds();}
  function createUnit(kind,x,y,team='blue'){const f=factions[faction],s=unitStats[kind];return{id:'u'+(++serial),kind,team,name:kind==='infantry'?f.infantry:kind==='tank'?f.tank:kind==='scout'?f.scout:f.collector,type:s.type,icon:s.icon,x:clamp(x,.02,.98),y:clamp(y,.02,.98),hp:s.hp,max:s.hp,speed:s.speed,range:s.range,damage:s.damage,rate:s.rate,radius:s.radius,cool:rand(.1,.8),target:null,move:null,harvesting:false,carry:0}}
  function toast(text){ui.toast.textContent=text;ui.toast.classList.add('show');toastTimer=2.3}
  function affordability(){return factionDefs[faction]}
  function available(kind){if(kind==='power'||kind==='barracks'||kind==='defense')return true;if(kind==='factory')return buildings.some(b=>b.team==='blue'&&b.kind==='barracks');if(kind==='tank'||kind==='scout'||kind==='collector')return buildings.some(b=>b.team==='blue'&&b.kind==='factory');if(kind==='infantry')return buildings.some(b=>b.team==='blue'&&b.kind==='barracks');return false}
  function refreshUI(){ui.credits.textContent=Math.floor(credits).toLocaleString();const collectors=units.filter(u=>u.team==='blue'&&u.kind==='collector').length;ui.income.textContent=collectors?'+'+(collectors*600).toLocaleString()+'/min':'$0/min';ui.army.textContent=String(units.filter(u=>u.team==='blue').length).padStart(2,'0');ui.power.textContent=buildings.some(b=>b.team==='blue'&&b.kind==='power')?'STABLE':'LOW';ui.power.style.color=buildings.some(b=>b.team==='blue'&&b.kind==='power')?'':'#e5a84c';
    const s=selected;if(!s){ui.type.textContent='BATTLE GROUP';ui.name.textContent=selectedIds.length?selectedIds.length+' units selected':'Select a unit or building';ui.icon.textContent='⌖';ui.health.style.width='0%'}else{ui.type.textContent=s.type||'UNIT';ui.name.textContent=s.name;ui.icon.textContent=s.icon||'⌂';ui.health.style.width=(100*s.hp/s.max)+'%';ui.health.style.background=s.hp/s.max<.3?'#df6451':'#c8f05b'}
    document.querySelectorAll('.action-card').forEach(b=>b.classList.toggle('selected-action',b.dataset.action===action));document.querySelectorAll('.build-card').forEach(b=>{b.disabled=credits<(affordability()[b.dataset.build]||0)||!available(b.dataset.build)||!playing||paused||over});}
  function renderBuilds(){const list=$('build-list'),f=factions[faction],costs=affordability();let data=activeTab==='structures'?[['power',f.power,'Power supply'],['barracks',f.barracks,'Train infantry'],['factory',f.factory,'Build vehicles']]:activeTab==='units'?[['infantry',f.infantry,'Rifle infantry'],['scout',f.scout,'Fast recon'],['tank',f.tank,'Main battle tank'],['collector',f.collector,'Harvest supplies']]:[['defense',f.defense,'Automated perimeter gun']];$('build-category').textContent=activeTab.toUpperCase();list.innerHTML=data.map(([key,label,sub])=>`<button class="build-card" data-build="${key}" title="${sub}"><span class="unit-art ${key}-art">${key==='power'?'ϟ':key==='tank'?'▰':key==='infantry'?'♟':key==='collector'?'⬡':key==='defense'?'⊕':key==='scout'?'◈':'▤'}</span><span class="build-copy"><b>${label}</b><small>${sub} <i>·</i> $${costs[key]}</small></span><span class="build-price">${costs[key]}</span></button>`).join('');list.querySelectorAll('.build-card').forEach(b=>b.onclick=()=>beginBuild(b.dataset.build));refreshUI()}
  function beginBuild(kind){if(!playing||paused||over)return;let cost=affordability()[kind];if(credits<cost){toast('NOT ENOUGH SUPPLIES');return}if(!available(kind)){toast(kind==='factory'?'BUILD A BARRACKS FIRST':'BUILD A WAR FACTORY FIRST');return}credits-=cost;if(unitStats[kind]){const base=buildings.find(b=>b.team==='blue'&&(kind==='infantry'?b.kind==='barracks':b.kind==='tank'||kind==='scout'||kind==='collector'?b.kind==='factory':false))||buildings.find(b=>b.team==='blue'&&b.kind==='hq');const u=createUnit(kind,base.x+.045,base.y+.03);u.move={x:base.x+.08,y:base.y+.08};units.push(u);toast(factions[faction][kind].toUpperCase()+' DEPLOYED')}else{placement=kind;toast('SELECT A CLEAR LOCATION FOR '+factions[faction][kind].toUpperCase())}refreshUI()}
  function screenPos(x,y){return{x:(x-camera.x)*camera.z+.5,y:(y-camera.y)*camera.z+.5}}
  function worldPos(x,y){return{x:(x/width-.5)/camera.z+camera.x,y:(y/height-.5)/camera.z+camera.y}}
  function dist(a,b){const p=screenPos(a.x,a.y),q=screenPos(b.x,b.y);return Math.hypot((p.x-q.x)*width,(p.y-q.y)*height)}
  function onPointer(e){if(!playing||paused||over)return;const rect=canvas.getBoundingClientRect(),p={x:e.clientX-rect.left,y:e.clientY-rect.top},w=worldPos(p.x,p.y);if(placement){if(w.x<.025||w.x>.975||w.y<.03||w.y>.97){toast('LOCATION OUTSIDE THEATER');return}if(buildings.some(b=>dist(b,w)<b.size+30)||units.some(u=>dist(u,w)<22)){toast('LOCATION OBSTRUCTED');return}buildings.push(makeBuilding(placement,'blue',w.x,w.y));toast(factions[faction][placement].toUpperCase()+' OPERATIONAL');placement=null;refreshUI();return}
    const actors=[...enemies,...buildings,...units].reverse();let hit=actors.find(a=>dist(a,w)<(a.size||a.radius*2||14)+12);
    if(action==='move'&&selected){for(const id of selectedIds){let u=units.find(v=>v.id===id);if(u){u.move={...w};u.target=null;u.harvesting=false}}if(selected.kind!=='building'){selected.move={...w};selected.target=null;selected.harvesting=false}action='select';refreshUI();return}
    if(action==='harvest'){let u=selected;if(u&&u.kind==='collector'){const node=nodes.filter(n=>n.active).sort((a,b)=>dist(a,w)-dist(b,w))[0];if(node){u.target=null;u.harvesting=true;u.harvestNode=node;u.move={x:node.x,y:node.y};toast('HARVESTER ROUTE SET')}}else toast('SELECT A HARVESTER FIRST');action='select';refreshUI();return}
    if(action==='attack'){if(selected&&selected.team==='blue'&&selected.kind!=='building'){if(hit&&hit.team==='red'){selected.target=hit;selected.move=null}else{selected.target=buildings.find(b=>b.team==='red'&&b.kind==='hq');selected.move={...w}}}action='select';refreshUI();return}
    if(hit){if(hit.team==='red'){if(selected&&selected.team==='blue'&&selected.kind!=='building'){selected.target=hit;selected.move=null}else toast('HOSTILE TARGET — SELECT A COMBAT UNIT')}else{selected=hit;selectedIds=hit.kind==='building'?[]:[hit.id];refreshUI()}return}
    if(selected&&selected.kind!=='building'){selected.move={...w};selected.target=null;selected.harvesting=false;toast('ORDERS RECEIVED')}else{selected=null;selectedIds=[];refreshUI()}}
  canvas.addEventListener('pointerdown',onPointer);
  document.querySelectorAll('.action-card').forEach(b=>b.onclick=()=>{if(!playing)return;action=b.dataset.action;if(action!=='select')toast(action==='move'?'SELECT DESTINATION':action==='harvest'?'SELECT A HARVESTER':'SELECT HOSTILE TARGET');refreshUI()});
  document.querySelectorAll('.build-tab').forEach(b=>b.onclick=()=>{activeTab=b.dataset.tab;document.querySelectorAll('.build-tab').forEach(t=>t.classList.toggle('active',t===b));renderBuilds()});
  document.querySelectorAll('.faction-option').forEach(b=>b.onclick=()=>{faction=b.dataset.faction;document.querySelectorAll('.faction-option').forEach(t=>t.classList.toggle('active',t===b));$('deploy-faction').textContent=faction.toUpperCase();$('faction-label').textContent=factions[faction].label});
  $('start-btn').onclick=()=>{ui.start.classList.add('hidden');$('faction-label').textContent=factions[faction].label;setup();playing=true;last=performance.now();toast(factions[faction].label+' DEPLOYED · HARVEST AND EXPAND');refreshUI()};
  $('pause-btn').onclick=()=>{if(!playing||over)return;paused=!paused;ui.pause.classList.toggle('hidden',!paused);$('pause-btn').textContent=paused?'▶':'Ⅱ';last=performance.now()};$('resume-btn').onclick=()=>{$('pause-btn').click()};
  $('restart-btn').onclick=$('again-btn').onclick=()=>{setup();ui.end.classList.add('hidden');ui.pause.classList.add('hidden');ui.start.classList.remove('hidden');playing=false;refreshUI()};
  $('sound-btn').onclick=e=>{e.currentTarget.classList.toggle('muted');toast('SOUND EFFECTS '+(e.currentTarget.classList.contains('muted')?'OFF':'ON'))};
  window.addEventListener('keydown',e=>{if(['INPUT','BUTTON'].includes(document.activeElement.tagName)&&e.key!=='Escape')return;if(e.key==='Escape'){if(placement){placement=null;toast('PLACEMENT CANCELLED')}else $('pause-btn').click()}if(e.key==='q')document.querySelector('[data-action="select"]').click();if(e.key==='w'&&!e.ctrlKey&&!e.metaKey)document.querySelector('[data-action="move"]').click();if(e.key==='e')document.querySelector('[data-action="attack"]').click();if(e.key==='r')document.querySelector('[data-action="harvest"]').click();const k=e.key.toLowerCase();if(['arrowup','arrowdown','arrowleft','arrowright'].includes(k)){e.preventDefault();camera.y+=k==='arrowup'?-0.04:k==='arrowdown'?.04:0;camera.x+=k==='arrowleft'?-0.04:k==='arrowright'?.04:0;}});
  canvas.addEventListener('wheel',e=>{e.preventDefault();camera.z=clamp(camera.z*(e.deltaY<0?1.12:.9),.8,1.8)},{passive:false});
  function shoot(a,b,damage){shots.push({x:a.x,y:a.y,tx:b.x,ty:b.y,target:b,damage,life:.2,max:.2,color:a.team==='blue'?factions[faction].accent:'#ee7859'});a.cool=a.rate||1}
  function update(dt){if(!playing||paused||over)return;time+=dt;enemyTimer-=dt;if(enemyTimer<=0){spawnEnemy();enemyTimer=Math.max(9,18-time*.012)+rand(-2,3)}
    for(const u of [...units,...enemies,...buildings]){if(u.hp<=0)continue;u.cool-=dt;if(u.kind==='collector'&&u.team==='blue'&&u.harvesting){const node=u.harvestNode;if(!node||!node.active){u.harvesting=false;u.harvestNode=null;u.move=null}else if(dist(u,node)<22){u.move=null;if(u.carry<300){const amount=Math.min(90*dt,300-u.carry,node.amount);u.carry+=amount;node.amount-=amount;if(node.amount<=0){node.active=false;u.harvestNode=null;u.move={x:.17,y:.54}}}else{u.harvestNode=null;u.harvesting=false;u.move={x:.17,y:.54}}}}
      if(u.kind==='collector'&&u.team==='blue'&&!u.harvesting&&u.carry>0&&dist(u,{x:.17,y:.54})<35){credits+=u.carry;u.carry=0;const node=nodes.find(n=>n.active);if(node){u.harvesting=true;u.harvestNode=node;u.move={x:node.x,y:node.y}}}
      if(u.range>0){if(u.target&&(!valid(u.target)||dist(u,u.target)>u.range*1.6))u.target=null;if(!u.target){let nearest=null,nd=Infinity;const candidates=u.team==='blue'?[...enemies,...buildings.filter(b=>b.team==='red')]:[...units.filter(v=>v.team==='blue'),...buildings.filter(b=>b.team==='blue')];for(const v of candidates){const d=dist(u,v);if(d<u.range&&d<nd){nearest=v;nd=d}}if(nearest)u.target=nearest}if(u.target&&dist(u,u.target)<u.range){if(u.cool<=0)shoot(u,u.target,u.damage);continue}}
      let target=u.move||(u.team==='red'&&!u.move?{x:.13,y:.53}:null);if(target){const dx=(target.x-u.x)*width,dy=(target.y-u.y)*height,d=Math.hypot(dx,dy);if(d>9){const step=Math.min(d,u.speed*dt);u.x=clamp(u.x+dx/d*step/width,.01,.99);u.y=clamp(u.y+dy/d*step/height,.01,.99)}else if(u.move)u.move=null}}
