function finish(win){over=true;playing=false;ui.end.classList.remove('hidden');$('end-kicker').textContent=win?'OPERATION COMPLETE':'FIELD REPORT';$('end-title').textContent=win?'VICTORY':'DEFEAT';$('end-copy').textContent=win?'Enemy command center neutralized. The frontier is yours.':'Your command center has fallen. Regroup and try another faction.';ui.objective.classList.toggle('done',win);}
function update(dt){if(!playing||paused||over)return;time+=dt;enemyClock-=dt;if(enemyClock<=0){spawnEnemy();enemyClock=Math.max(9,19-time*.012)+rand(-2,3);}
  for(const u of [...units,...enemies,...buildings]){if(u.hp<=0)continue;u.cool-=dt;
    if(u.kind==='collector'&&u.team==='blue'&&u.harvesting){const node=u.harvestNode;if(!node||!node.active){u.harvesting=false;u.harvestNode=null;u.move=null;}else if(distance(u,node)<22){u.move=null;if(u.carry<300){const amount=Math.min(100*dt,300-u.carry,node.amount);u.carry+=amount;node.amount-=amount;if(node.amount<=0){node.active=false;u.harvestNode=null;u.harvesting=false;u.move={x:.13,y:.53};}}else{u.harvestNode=null;u.harvesting=false;u.move={x:.13,y:.53};}}}
    if(u.kind==='collector'&&u.team==='blue'&&!u.harvesting&&u.carry>0&&distance(u,{x:.13,y:.53})<36){credits+=u.carry;u.carry=0;const node=nodes.find(n=>n.active);if(node){u.harvestNode=node;u.harvesting=true;u.move={x:node.x,y:node.y};}}
