       if(u.kind==='collector'&&u.team==='blue'&&!u.harvesting&&u.carry>0&&distance(u,{x:.13,y:.53})<36){credits+=u.carry;u.carry=0;const node=nodes.find(n=>n.active);if(node){u.harvestNode=node;u.harvesting=true;u.move={x:node.x,y:node.y};}}
       if(u.range>0){if(u.target&&(!valid(u.target)||distance(u,u.target)>u.range*1.7))u.target=null;if(!u.target){let nearest=null,nd=Infinity;const candidates=u.team==='blue'?[...enemies,...buildings.filter(b=>b.team==='red')]:[...units.filter(v=>v.team==='blue'),...buildings.filter(b=>b.team==='blue')];for(const v of candidates){const d=distance(u,v);if(d<u.range&&d<nd){nearest=v;nd=d;}}if(nearest)u.target=nearest;}if(u.target&&distance(u,u.target)<=u.range){if(u.cool<=0)fire(u,u.target);continue;}}
       let dest=u.move||(u.team==='red'?{x:.13,y:.53}:null);if(dest){const dx=(dest.x-u.x)*width,dy=(dest.y-u.y)*height,d=Math.hypot(dx,dy);if(d>9){const step=Math.min(d,u.speed*dt);u.x=clamp(u.x+dx/d*step/width,.01,.99);u.y=clamp(u.y+dy/d*step/height,.01,.99);}else if(u.move)u.move=null;}
