import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const browser=await chromium.launch({headless:true});
const page=await browser.newPage({viewport:{width:1440,height:900}});
const errors=[];page.on('pageerror',e=>errors.push(e.message));
await page.goto('http://localhost:3000');await page.locator('#start-btn').click();
const canvas=page.locator('#battlefield'),box=await canvas.boundingBox();
await page.locator('[data-build="barracks"]').click();await canvas.click({position:{x:box.width*.31,y:box.height*.28}});
await page.locator('[data-build="factory"]').click();await canvas.click({position:{x:box.width*.38,y:box.height*.28}});
await page.locator('[data-tab="units"]').click();await page.locator('[data-build="collector"]').click();
await page.waitForTimeout(3000);
await canvas.click({position:{x:box.width*.44,y:box.height*.33}});
const selected=await page.locator('#selection-name').textContent();
await page.locator('[data-action="harvest"]').click();await canvas.click({position:{x:box.width*.5,y:box.height*.5}});
const order=await page.locator('#toast').textContent();
const before=Number((await page.locator('#credits').textContent()).replaceAll(',',''));
await page.waitForTimeout(42000);
const after=Number((await page.locator('#credits').textContent()).replaceAll(',',''));
console.log(JSON.stringify({selected,order,before,after,harvestDeposited:after>before,errors},null,2));
await browser.close();

